	"updated_at" timestamp with time zone,
	CONSTRAINT "ck_products_qty" CHECK ("products"."qty" >= 0),
	CONSTRAINT "ck_products_mrp" CHECK ("products"."mrp" >= 0),
	CONSTRAINT "ck_products_pack" CHECK ("products"."pack_size" > 0),
	CONSTRAINT "ck_products_dates" CHECK ("products"."best_before" >= "products"."packed_on")
);
